package com.franco.desco.adapter.in.web.inventory;
import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.inventory.InventoryCommands;import com.franco.desco.application.inventory.port.in.InventoryUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController@RequestMapping("/api/v1/inventario")@Tag(name="Inventario y vehículos",description="Bienes, vehículos, suministros y movimientos de inventario.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class InventoryController{private final InventoryUseCase u;private final InventoryWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public InventoryController(InventoryUseCase u,InventoryWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping("/bienes")@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_LISTAR')")@Operation(operationId="inventarioBienesListar",summary="Listar bienes")public ResponseEntity<ApiResponse<PageResponse<InventoryResponses.AssetSummary>>>assets(@RequestParam(required=false)Long empresaId,@RequestParam(required=false)Long tipoBienId,@RequestParam(required=false)String estadoBien,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.listAssets(map.assets(pagina,tamano,empresaId,tipoBienId,estadoBien),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/bienes/{id}")@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_VER')")@Operation(operationId="inventarioBienesVer",summary="Ver bien")public ResponseEntity<ApiResponse<InventoryResponses.AssetDetail>>asset(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.getAsset(new InventoryCommands.GetAsset(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping("/bienes")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_CREAR')")@Operation(operationId="inventarioBienesCrear",summary="Registrar bien")public ResponseEntity<ApiResponse<InventoryResponses.Created>>createAsset(@Valid@RequestBody InventoryRequests.CreateAsset q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.createAsset(new InventoryCommands.CreateAsset(q.empresaId(),q.tipoBienId(),q.codigoPatrimonial(),q.nombre(),q.marca(),q.modelo(),q.serie()),ids.resolve(a),meta.resolve(r)),r,InventoryResponses.Created::new);}
 @PutMapping("/bienes/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_EDITAR')")@Operation(operationId="inventarioBienesEditar",summary="Editar bien")public ResponseEntity<ApiResponse<Void>>updateAsset(@PathVariable Long id,@Valid@RequestBody InventoryRequests.UpdateAsset q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updateAsset(new InventoryCommands.UpdateAsset(id,q.nombre(),q.marca(),q.modelo(),q.serie(),q.estadoBien()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/bienes/{id}/baja")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_RETIRAR')")@Operation(operationId="inventarioBienesBaja",summary="Dar de baja un bien")public ResponseEntity<ApiResponse<Void>>retireAsset(@PathVariable Long id,@Valid@RequestBody InventoryRequests.RetireAsset q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.retireAsset(new InventoryCommands.RetireAsset(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/bienes/{id}/vehiculo")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_CREAR')")@Operation(operationId="inventarioVehiculosRegistrar",summary="Registrar datos de vehículo para un bien")public ResponseEntity<ApiResponse<InventoryResponses.Created>>vehicle(@PathVariable Long id,@Valid@RequestBody InventoryRequests.RegisterVehicle q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.registerVehicle(new InventoryCommands.RegisterVehicle(id,q.placa(),q.tipoVehiculo(),q.kilometrajeKm()),ids.resolve(a),meta.resolve(r)),r,InventoryResponses.Created::new);}
 @PutMapping("/vehiculos/{id}/kilometraje")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_EDITAR')")@Operation(operationId="inventarioVehiculosKilometraje",summary="Actualizar kilometraje")public ResponseEntity<ApiResponse<Void>>mileage(@PathVariable Long id,@Valid@RequestBody InventoryRequests.UpdateMileage q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updateMileage(new InventoryCommands.UpdateMileage(id,q.kilometrajeKm()),ids.resolve(a),meta.resolve(r)),r);}
 @GetMapping("/suministros")@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_LISTAR')")@Operation(operationId="inventarioSuministrosListar",summary="Listar suministros")public ResponseEntity<ApiResponse<PageResponse<InventoryResponses.Supply>>>supplies(@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.listSupplies(map.supplies(pagina,tamano),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @PostMapping("/suministros")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_CREAR')")@Operation(operationId="inventarioSuministrosCrear",summary="Registrar suministro")public ResponseEntity<ApiResponse<InventoryResponses.Created>>createSupply(@Valid@RequestBody InventoryRequests.CreateSupply q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.createSupply(new InventoryCommands.CreateSupply(q.codigo(),q.nombre(),q.unidadMedida(),q.stockInicial()),ids.resolve(a),meta.resolve(r)),r,InventoryResponses.Created::new);}
 @PutMapping("/suministros/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_EDITAR')")@Operation(operationId="inventarioSuministrosEditar",summary="Editar suministro")public ResponseEntity<ApiResponse<Void>>updateSupply(@PathVariable Long id,@Valid@RequestBody InventoryRequests.UpdateSupply q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updateSupply(new InventoryCommands.UpdateSupply(id,q.nombre(),q.unidadMedida()),ids.resolve(a),meta.resolve(r)),r);}
 @GetMapping("/suministros/kardex")@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_VER')")@Operation(operationId="inventarioSuministrosKardex",summary="Consultar kardex de suministros")public ResponseEntity<ApiResponse<List<InventoryResponses.SupplyMovement>>>kardex(@RequestParam(required=false)Long suministroId,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.supplyMovements(new InventoryCommands.ListSupplyMovements(suministroId),ids.resolve(a),meta.resolve(r)),r,l->l.stream().map(map::response).toList());}
 @PostMapping("/suministros/{id}/movimientos")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'INVENTARIO_EDITAR')")@Operation(operationId="inventarioSuministrosMovimientoRegistrar",summary="Registrar entrada o ajuste de suministro")public ResponseEntity<ApiResponse<InventoryResponses.Created>>adjust(@PathVariable Long id,@Valid@RequestBody InventoryRequests.AdjustSupply q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.adjustSupply(new InventoryCommands.AdjustSupply(id,q.tipoMovimiento(),q.cantidad(),q.documentoReferencia(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,InventoryResponses.Created::new);}
}
